LAT_BBOX = (145.496094, 656.6875, 943.667969, 802.492188)  # bbox of the Latin "BUDDHZ" mark

BRAND_GREEN = "#1E9771"


def logo_group(paths, bbox, cx, cy, width, fill=BRAND_GREEN):
    """Return a <g> with the given mark scaled to `width`, centred on (cx, cy)."""
    minx, miny, maxx, maxy = bbox
    s = width / (maxx - minx)
    tx = cx - (maxx + minx) / 2 * s
    ty = cy - (maxy + miny) / 2 * s
    body = "".join(f'<path d="{d}"/>' for d in paths)
    return f'<g transform="translate({tx:.1f} {ty:.1f}) scale({s:.4f})" fill="{fill}">{body}</g>'
